use super::preamble::*;
#[derive(Clone, Debug, Eq, PartialEq, Hash)]
pub struct OpNop {}
impl<'a> Inst<'a> for OpNop {
    const META: &'static InstMeta = &OP_NOP;
    type MaybeIdResult = ();
    fn id_result(&mut self) -> &mut Self::MaybeIdResult {
        make_mut_ref_unit()
    }
}
impl<'a> InstEncoding<'a> for OpNop {
    fn encode(&self, writer: &mut impl WordWriter) -> Result<(), EncodeError> {
        let len = 1;
        writer.write_op(Self::META.opcode, len)?;
        Ok(())
    }
    fn decode(reader: InstReader<'a>) -> Result<Self, DecodeError> {
        reader.check_opcode(Self::META)?;
        Ok(Self {})
    }
    fn dis_fmt(&self, f: &mut Formatter<'_>, _ctx: &DisContext) -> std::fmt::Result {
        write!(f, "OpNop")
    }
}
#[derive(Clone, Debug, Eq, PartialEq, Hash)]
pub struct OpUndef {
    pub id_result_type: IdResultType,
    pub id_result: OptionIdResult,
}
impl<'a> Inst<'a> for OpUndef {
    const META: &'static InstMeta = &OP_UNDEF;
    type MaybeIdResult = OptionIdResult;
    fn id_result(&mut self) -> &mut Self::MaybeIdResult {
        &mut self.id_result
    }
}
impl<'a> InstEncoding<'a> for OpUndef {
    fn encode(&self, writer: &mut impl WordWriter) -> Result<(), EncodeError> {
        let len = 1
            + OperandEncoding::word_len(&self.id_result_type)
            + OperandEncoding::word_len(&self.id_result);
        writer.write_op(Self::META.opcode, len)?;
        OperandEncoding::encode(&self.id_result_type, &mut *writer)?;
        OperandEncoding::encode(&self.id_result, &mut *writer)?;
        Ok(())
    }
    fn decode(reader: InstReader<'a>) -> Result<Self, DecodeError> {
        let mut op_reader = reader.check_opcode(Self::META)?;
        Ok(Self {
            id_result_type: OperandEncoding::decode(&mut op_reader)?,
            id_result: OperandEncoding::decode_last(&mut op_reader)?,
        })
    }
    fn dis_fmt(&self, f: &mut Formatter<'_>, _ctx: &DisContext) -> std::fmt::Result {
        let rspirv_space = _ctx.rspirv_space();
        write!(
            f,
            "{} = OpUndef{rspirv_space}{}",
            self.id_result.dis(_ctx),
            self.id_result_type.dis(_ctx)
        )
    }
}
